mutations.before:
return hasAllowedImageMagic(bytes)
  ? undefined
  : `${JSON.stringify(name)} is not a PNG or JPEG file.`;

if (flags.switchedAt === undefined) {
  return { ok: false, reason: SWITCHED_AT_REQUIRED };
}

if (st.isSymbolicLink()) {
  return {
    ref,
    kind: "unsafe",
    reason: "the ref is a symlink; the importer never follows one",
  };
}
